<article class="car-card"><a href="<?= url('/mobil/'.$car['id']) ?>"><div class="thumb"><?php if($car['image']): ?><img src="<?= url($car['image']) ?>" alt="<?= e($car['title']) ?>" loading="lazy"><?php else: ?><div class="placeholder">🚘</div><?php endif; ?><span class="badge"><?= e($car['year']) ?></span></div><div class="card-body"><div class="muted"><?= e($car['brand']) ?> · <?= number_format((int)$car['mileage'],0,',','.') ?> km</div><h3><?= e($car['title']) ?></h3><div class="specs"><span><?= e($car['transmission']) ?></span><span><?= e($car['fuel']) ?></span><span><?= e($car['city']) ?></span></div><strong class="price">Rp <?= number_format((int)$car['price'],0,',','.') ?></strong></div></a></article>
